"""Format specifications."""

def run() -> None:
    pi = 3.14159265
    n = 1234567
    neg = -42
    name = "héllo"
    flag = True
    big = 1234567.891
    print(f"[{pi:.2f}] [{pi:10.3f}] [{pi:<10.1f}] [{pi:^10.4f}] [{pi:+.2f}] [{-pi: .1f}]")
    print(f"[{n:,}] [{n:_}] [{n:>12,}] [{neg:05d}] [{neg:=+8}] [{n:+d}] [{0:d}]")
    print(f"[{255:x}] [{255:X}] [{255:#x}] [{255:#010b}] [{8:o}] [{255:_b}]")
    print(f"[{big:,.2f}] [{big:e}] [{big:.3e}] [{big:g}] [{0.00001234:g}] [{big:.3}]")
    print(f"[{0.256:.1%}] [{0.5:%}] [{2.0:.3}] [{-0.001:.1f}] [{1e16:}] [{2.5:8}]")
    print(f"[{name:>8}] [{name:*^9}] [{name:.3}] [{name:<7}|] [{name!r}] [{n!r}]")
    print(f"[{flag}] [{flag:>6}] [{3:.2f}] [{7:e}] [{1e-5:g}] [{100000.0:g}] [{1e6:g}]")
    print(f"[{pi:08.3f}] [{-pi:08.3f}] [{12:<5}|] [{12:^6}] [{'ab':_>5}] [{0.0:e}] [{1.5:G}]")
    print(f"[{2.675:.2f}] [{0.125:.2f}] [{0.375:.2f}] [{1e300:.2e}] [{123.456:.0f}] [{0.5:.0f}] [{1.5:.0f}]")
